  if(dly){ const d=Math.max(1,Math.round(fx.delay.time*(tv&&!tv.tm.constant?tv.tm.slowBeat:beat)*SR)), fb=clamp(fx.delay.fb,0,.92); tail+=Math.min(8*SR,d*((fb>0?Math.ceil(Math.log(.001)/Math.log(fb)):0)+1)); }
